/*!
 * \file ai_infra_scatter_block_update_tiling.h
 * \brief
 */
#ifndef __OP_HOST_AI_INFRA_SCATTER_BLOCK_UPDATE_H__
#define __OP_HOST_AI_INFRA_SCATTER_BLOCK_UPDATE_H__

#include <tiling/tiling_api.h>
#include "register/tilingdata_base.h"
#include "../../../common/include/tiling_base/tiling_base.h"
#include "../../../common/include/err/ops_err.h"

namespace optiling {

BEGIN_TILING_DATA_DEF(AiInfraScatterBlockUpdateTilingData)
TILING_DATA_FIELD_DEF(int64_t, totalIndicesCount);
TILING_DATA_FIELD_DEF(int64_t, updateDimSize);
TILING_DATA_FIELD_DEF(int32_t, totalCoreNum);
TILING_DATA_FIELD_DEF(int64_t, ubSize);
TILING_DATA_FIELD_DEF(int64_t, eachCoreIndexCount);
TILING_DATA_FIELD_DEF(int32_t, usedCoreNum);
TILING_DATA_FIELD_DEF(int64_t, tailCoreIndexCount);
TILING_DATA_FIELD_DEF(int64_t, oneIndexSize);
TILING_DATA_FIELD_DEF(int64_t, oneUpdateAlignSize);
TILING_DATA_FIELD_DEF(int64_t, indicesPerLoad);
TILING_DATA_FIELD_DEF(int64_t, maxIndicesPerLoad);
TILING_DATA_FIELD_DEF(int64_t, inputStride0);
TILING_DATA_FIELD_DEF(int64_t, inputStride1);
TILING_DATA_FIELD_DEF(int64_t, indicesTypeSize);
TILING_DATA_FIELD_DEF(int64_t, updateTypeSize);
END_TILING_DATA_DEF;

REGISTER_TILING_DATA_CLASS(AiInfraScatterBlockUpdate, AiInfraScatterBlockUpdateTilingData);

struct AiInfraScatterBlockUpdateCompileInfo {
    uint64_t aivNum{0UL};
    uint64_t ubSize{0UL};
};

class AiInfraScatterBlockUpdateBaseTiling : public Ops::Transformer::OpTiling::TilingBaseClass {
public:
    explicit AiInfraScatterBlockUpdateBaseTiling(gert::TilingContext* context)
        : Ops::Transformer::OpTiling::TilingBaseClass(context) {};

    ~AiInfraScatterBlockUpdateBaseTiling() override = default;

protected:
    bool IsCapable() override
    {
        return true;
    };
    // 1、获取平台信息比如CoreNum、UB/L1/L0C资源大小
    ge::graphStatus GetPlatformInfo() override;
    // 2、获取INPUT/OUTPUT/ATTR信息
    ge::graphStatus GetShapeAttrsInfo() override
    {
        return ge::GRAPH_SUCCESS;
    };
    // 3、计算数据切分TilingData
    ge::graphStatus DoOpTiling() override;
    // 4、计算高阶API的TilingData
    ge::graphStatus DoLibApiTiling() override
    {
        return ge::GRAPH_SUCCESS;
    };
    // 5、计算TilingKey
    uint64_t GetTilingKey() const override;
    // 6、计算Workspace 大小
    ge::graphStatus GetWorkspaceSize() override
    {
        return ge::GRAPH_SUCCESS;
    };
    // 7、保存Tiling数据
    ge::graphStatus PostTiling() override;

    ge::graphStatus GetAndCheckInputShape();
    ge::graphStatus GetInputShapeAndStride();
    ge::graphStatus GetIndicesShape();
    ge::graphStatus GetUpdateShape();
    ge::graphStatus ValidateShapeRange();
    ge::graphStatus CalcDataTypeSize();
    void PrintTilingData();

private:
    AiInfraScatterBlockUpdateTilingData tilingData_;
    uint64_t aivNum_ = 20;
    int64_t ubSize_ = 0;

    // input (var) shape: (b_n, b_s, D), 支持第0维非连续
    int64_t bn_ = 0;
    int64_t bs_ = 0;
    int64_t D_ = 0;
    int64_t inputStride0_ = 0; // input第0维stride（元素数），非连续时可能 != bs_ * D_
    int64_t inputStride1_ = 0; // input第1维stride（元素数），通常 = D_

    // indices shape: (T, 2)
    int64_t T_ = 0;

    // update shape: (T, D)
    int64_t updateDimSize_ = 0;

    // 数据类型
    ge::DataType inputDtype_ = ge::DT_FLOAT;
    ge::DataType indicesDtype_ = ge::DT_INT32;
    int64_t indicesTypeSize_ = 0;
    int64_t updateTypeSize_ = 0;

    // tiling计算结果
    int64_t totalIndicesCount_ = 0;
    int32_t totalCoreNum_ = 0;
    int64_t eachCoreIndexCount_ = 0;
    int32_t usedCoreNum_ = 0;
    int64_t tailCoreIndexCount_ = 0;
    int64_t oneIndexSize_ = 0;
    int64_t oneUpdateAlignSize_ = 0;
    int64_t indicesPerLoad_ = 0;
    int64_t maxIndicesPerLoad_ = 0;
};

} // namespace optiling
#endif // __OP_HOST_AI_INFRA_SCATTER_BLOCK_UPDATE_H__

