11	/*!
12	 * \file ai_infra_scatter_block_update_tiling.cpp
13	 * \brief
14	 */
15	
16	#include <algorithm>
17	#include "../../../common/include/tiling_base/tiling_templates_registry.h"
18	#include "register/op_def_registry.h"
19	#include "platform/platform_infos_def.h"
20	#include "../../../common/include/err/ops_err.h"
21	#include "ai_infra_scatter_block_update_tiling.h"
22	
23	namespace optiling {
24	
25	using namespace Ops::Transformer::OpTiling;
26	
27	// 输入tensor索引
28	static constexpr uint32_t INPUT_VAR_INDEX = 0;
29	static constexpr uint32_t INPUT_INDICES_INDEX = 1;
30	static constexpr uint32_t INPUT_UPDATE_INDEX = 2;
31	
32	// 维度常量
33	static constexpr int64_t INPUT_DIM_NUM = 3;     // input shape: (b_n, b_s, D)
34	static constexpr int64_t INDICES_DIM_NUM = 2;   // indices shape: (T, 2)
35	static constexpr int64_t UPDATE_DIM_NUM = 2;    // update shape: (T, D)
36	static constexpr int64_t INDICES_LAST_DIM = 2;  // indices最后一维固定为2
37	
38	// input维度索引
39	static constexpr int64_t INPUT_DIM_BN_INDEX = 0;  // input第0维索引 (b_n)
40	static constexpr int64_t INPUT_DIM_BS_INDEX = 1;  // input第1维索引 (b_s)
41	static constexpr int64_t INPUT_DIM_D_INDEX = 2;   // input第2维索引 (D)
42	
43	// 内存对齐与UB布局
44	static constexpr int64_t ALIGN_BYTES = 32;
45	static constexpr int64_t RESERVED_UB_SIZE = 4 * 1024;  // 4KB预留给栈和临时变量
46	static constexpr int64_t DOUBLE_BUFFER_NUM = 2;
47	static constexpr int64_t DATA_COPY_MAX_BLOCK = 4064;
48	
49	// shape取值范围约束 (闭区间)
50	static constexpr int64_t BN_MIN = 1;
51	static constexpr int64_t BN_MAX = 2 * 1024 * 1024;       // 2M
52	static constexpr int64_t BS_MIN = 1;
53	static constexpr int64_t BS_MAX = 1024;
54	static constexpr int64_t D_MIN = 1;
55	static constexpr int64_t D_MAX = 2048;
56	static constexpr int64_t T_MIN = 1;
57	static constexpr int64_t T_MAX = 1024 * 1024;       // 1M
58	
59	static constexpr uint64_t FULL_LOAD_TILING_KEY = 1000;
60	
61	
62	static inline int64_t AlignUp(int64_t size, int64_t alignment)
63	{
64	    if (alignment <= 0) {
65	        return size;
66	    }
67	    return (size + alignment - 1) / alignment * alignment;
68	}
69	
70	static inline int64_t CeilDiv(int64_t a, int64_t b)
71	{
72	    if (b <= 0) {
73	        return a;
74	    }
75	    return (a + b - 1) / b;
76	}
77	
78	REGISTER_TILING_TEMPLATE("AiInfraScatterBlockUpdate", AiInfraScatterBlockUpdateBaseTiling, 1000);
79	
80	
81	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetPlatformInfo()
82	{
83	    uint64_t aivNum = 40;
84	    uint64_t ubSize = 192 * 1024; // 192k: default ubSize
85	    auto platformInfoPtr = context_->GetPlatformInfo();
86	    if (platformInfoPtr == nullptr) {
87	        auto compilePtr = reinterpret_cast<const AiInfraScatterBlockUpdateCompileInfo *>(context_->GetCompileInfo());
88	        OP_CHECK_IF(compilePtr == nullptr, OP_LOGE(context_, "compile_info is null"),
89	                    return ge::GRAPH_FAILED);
90	        aivNum = compilePtr->aivNum;
91	        ubSize = compilePtr->ubSize;
92	    } else {
93	        auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
94	        aivNum = ascendcPlatform.GetCoreNumAiv();
95	        ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
96	    }
97	    aivNum_ = aivNum;
98	    ubSize_ = static_cast<int64_t>(ubSize);
99	
100	    return ge::GRAPH_SUCCESS;
101	}
102	
103	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetInputShapeAndStride()
104	{
105	    // ========== 获取input (var) 信息: shape (b_n, b_s, D), 支持第0维非连续 ==========
106	    auto inputDesc = context_->GetInputDesc(INPUT_VAR_INDEX);
107	    OP_CHECK_NULL_WITH_CONTEXT(context_, inputDesc);
108	    inputDtype_ = inputDesc->GetDataType();
109	
110	    // 校验input数据类型: 仅支持FP32/BF16/FP16/INT8
111	    OP_CHECK_IF(inputDtype_ != ge::DT_FLOAT && inputDtype_ != ge::DT_BF16 &&
112	                inputDtype_ != ge::DT_FLOAT16 && inputDtype_ != ge::DT_INT8,
113	        OP_LOGE(context_->GetNodeName(), "input dtype only supports FP32/BF16/FP16/INT8"),
114	        return ge::GRAPH_FAILED);
115	
116	    // 获取input shape和stride
117	    auto inputShapePtr = context_->GetInputShape(INPUT_VAR_INDEX);
118	    OP_CHECK_NULL_WITH_CONTEXT(context_, inputShapePtr);
119	
120	    auto* inputStride = context_->GetInputStride(INPUT_VAR_INDEX);
121	    if (inputStride != nullptr && inputStride->GetDimNum() > 0) {
122	        // 非连续tensor，通过input stride判断
123	        auto viewShape = inputShapePtr->GetShape();
124	        OP_CHECK_IF(viewShape.GetDimNum() != static_cast<size_t>(INPUT_DIM_NUM),
125	            OP_LOGE(context_->GetNodeName(),
126	                    "input should be 3D (b_n, b_s, D), but got %zu dims", viewShape.GetDimNum()),
127	            return ge::GRAPH_FAILED);
128	        bn_ = viewShape.GetDim(INPUT_DIM_BN_INDEX);
129	        bs_ = viewShape.GetDim(INPUT_DIM_BS_INDEX);
130	        D_ = viewShape.GetDim(INPUT_DIM_D_INDEX);
131	        inputStride0_ = (*inputStride)[0];
132	        inputStride1_ = (*inputStride)[1];
133	    } else {
134	        // 连续tensor, 从originShape计算stride
135	        auto originShape = inputShapePtr->GetOriginShape();
136	        OP_CHECK_IF(originShape.GetDimNum() != static_cast<size_t>(INPUT_DIM_NUM),
137	            OP_LOGE(context_->GetNodeName(),
138	                    "input should be 3D (b_n, b_s, D), but got %zu dims", originShape.GetDimNum()),
139	            return ge::GRAPH_FAILED);
140	        bn_ = originShape.GetDim(INPUT_DIM_BN_INDEX);
141	        bs_ = originShape.GetDim(INPUT_DIM_BS_INDEX);
142	        D_ = originShape.GetDim(INPUT_DIM_D_INDEX);
143	        inputStride0_ = bs_ * D_;
144	        inputStride1_ = D_;
145	    }
146	    return ge::GRAPH_SUCCESS;
147	}
148	
149	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetIndicesShape()
150	{
151	    // ========== 获取indices信息: shape (T, 2), 连续, INT32/INT64 ==========
152	    auto indicesDesc = context_->GetInputDesc(INPUT_INDICES_INDEX);
153	    OP_CHECK_NULL_WITH_CONTEXT(context_, indicesDesc);
154	    indicesDtype_ = indicesDesc->GetDataType();
155	
156	    OP_CHECK_IF(indicesDtype_ != ge::DT_INT32 && indicesDtype_ != ge::DT_INT64,
157	        OP_LOGE(context_->GetNodeName(), "indices dtype only supports INT32/INT64"),
158	        return ge::GRAPH_FAILED);
159	
160	    auto indicesShapePtr = context_->GetInputShape(INPUT_INDICES_INDEX);
161	    OP_CHECK_NULL_WITH_CONTEXT(context_, indicesShapePtr);
162	    auto indicesShape = indicesShapePtr->GetStorageShape();
163	
164	    OP_CHECK_IF(indicesShape.GetDimNum() != static_cast<size_t>(INDICES_DIM_NUM),
165	        OP_LOGE(context_->GetNodeName(),
166	                "indices should be 2D (T, 2), but got %zu dims", indicesShape.GetDimNum()),
167	        return ge::GRAPH_FAILED);
168	
169	    T_ = indicesShape.GetDim(0);
170	    int64_t indicesDim1 = indicesShape.GetDim(1);
171	    OP_CHECK_IF(indicesDim1 != INDICES_LAST_DIM,
172	        OP_LOGE(context_->GetNodeName(), "indices last dim should be 2, but got %ld", indicesDim1),
173	        return ge::GRAPH_FAILED);
174	    return ge::GRAPH_SUCCESS;
175	}
176	
177	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetUpdateShape()
178	{
179	    // ========== 获取update信息: shape (T, D), 连续, 与input同dtype ==========
180	    auto updateDesc = context_->GetInputDesc(INPUT_UPDATE_INDEX);
181	    OP_CHECK_NULL_WITH_CONTEXT(context_, updateDesc);
182	    auto updateDtype = updateDesc->GetDataType();
183	
184	    OP_CHECK_IF(updateDtype != inputDtype_,
185	        OP_LOGE(context_->GetNodeName(), "update dtype should be same as input dtype"),
186	        return ge::GRAPH_FAILED);
187	
188	    auto updateShapePtr = context_->GetInputShape(INPUT_UPDATE_INDEX);
189	    OP_CHECK_NULL_WITH_CONTEXT(context_, updateShapePtr);
190	    auto updateShape = updateShapePtr->GetStorageShape();
191	
192	    OP_CHECK_IF(updateShape.GetDimNum() != static_cast<size_t>(UPDATE_DIM_NUM),
193	        OP_LOGE(context_->GetNodeName(),
194	                "update should be 2D (T, D), but got %zu dims", updateShape.GetDimNum()),
195	        return ge::GRAPH_FAILED);
196	
197	    int64_t updateT = updateShape.GetDim(0);
198	    updateDimSize_ = updateShape.GetDim(1);
199	
200	    // 校验indices和update的T维一致
201	    OP_CHECK_IF(updateT != T_,
202	        OP_LOGE(context_->GetNodeName(),
203	                "update dim0(%ld) should match indices dim0(%ld)", updateT, T_),
204	        return ge::GRAPH_FAILED);
205	
206	    // 校验update的D维与input的D维一致
207	    OP_CHECK_IF(updateDimSize_ != D_,
208	        OP_LOGE(context_->GetNodeName(),
209	                "update dim1(%ld) should match input dim2(%ld)", updateDimSize_, D_),
210	        return ge::GRAPH_FAILED);
211	    return ge::GRAPH_SUCCESS;
212	}
213	
214	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::ValidateShapeRange()
215	{
216	    // ========== shape取值范围校验 ==========
217	    OP_CHECK_IF(bn_ < BN_MIN || bn_ > BN_MAX,
218	        OP_LOGE(context_->GetNodeName(),
219	                "b_n(%ld) out of range [%ld, %ld]", bn_, BN_MIN, BN_MAX),
220	        return ge::GRAPH_FAILED);
221	    OP_CHECK_IF(bs_ < BS_MIN || bs_ > BS_MAX,
222	        OP_LOGE(context_->GetNodeName(),
223	                "b_s(%ld) out of range [%ld, %ld]", bs_, BS_MIN, BS_MAX),
224	        return ge::GRAPH_FAILED);
225	    OP_CHECK_IF(D_ < D_MIN || D_ > D_MAX,
226	        OP_LOGE(context_->GetNodeName(),
227	                "D(%ld) out of range [%ld, %ld]", D_, D_MIN, D_MAX),
228	        return ge::GRAPH_FAILED);
229	    OP_CHECK_IF(T_ < T_MIN || T_ > T_MAX,
230	        OP_LOGE(context_->GetNodeName(),
231	                "T(%ld) out of range [%ld, %ld]", T_, T_MIN, T_MAX),
232	        return ge::GRAPH_FAILED);
233	    return ge::GRAPH_SUCCESS;
234	}
235	
236	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::CalcDataTypeSize()
237	{
238	    // ========== 计算数据类型大小 ==========
239	    indicesTypeSize_ = ge::GetSizeByDataType(indicesDtype_);
240	    OP_CHECK_IF(indicesTypeSize_ <= 0,
241	        OP_LOGE(context_->GetNodeName(), "get indicesTypeSize failed"),
242	        return ge::GRAPH_FAILED);
243	
244	    updateTypeSize_ = ge::GetSizeByDataType(inputDtype_);
245	    OP_CHECK_IF(updateTypeSize_ <= 0,
246	        OP_LOGE(context_->GetNodeName(), "get updateTypeSize failed"),
247	        return ge::GRAPH_FAILED);
248	    return ge::GRAPH_SUCCESS;
249	}
250	
251	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::GetAndCheckInputShape()
252	{
253	    if (GetInputShapeAndStride() != ge::GRAPH_SUCCESS) {
254	        return ge::GRAPH_FAILED;
255	    }
256	    if (GetIndicesShape() != ge::GRAPH_SUCCESS) {
257	        return ge::GRAPH_FAILED;
258	    }
259	    if (GetUpdateShape() != ge::GRAPH_SUCCESS) {
260	        return ge::GRAPH_FAILED;
261	    }
262	    if (ValidateShapeRange() != ge::GRAPH_SUCCESS) {
263	        return ge::GRAPH_FAILED;
264	    }
265	    if (CalcDataTypeSize() != ge::GRAPH_SUCCESS) {
266	        return ge::GRAPH_FAILED;
267	    }
268	
269	    OP_LOGD(context_->GetNodeName(),
270	        "input: (%ld,%ld,%ld), stride: (%ld,%ld), indices: (%ld,2), "
271	        "update: (%ld,%ld), indicesTypeSize=%ld, updateTypeSize=%ld",
272	        bn_, bs_, D_, inputStride0_, inputStride1_,
273	        T_, T_, updateDimSize_, indicesTypeSize_, updateTypeSize_);
274	
275	    return ge::GRAPH_SUCCESS;
276	}
277	
278	
279	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::DoOpTiling()
280	{
281	    if (GetAndCheckInputShape() != ge::GRAPH_SUCCESS) {
282	        OP_LOGE(context_->GetNodeName(), "GetAndCheckInputShape failed!");
283	        return ge::GRAPH_FAILED;
284	    }
285	
286	    totalIndicesCount_ = T_;
287	    totalCoreNum_ = static_cast<int32_t>(aivNum_);
288	
289	    // 处理空tensor
290	    if (totalIndicesCount_ == 0) {
291	        usedCoreNum_ = 1;
292	        eachCoreIndexCount_ = 0;
293	        tailCoreIndexCount_ = 0;
294	        oneIndexSize_ = 0;
295	        oneUpdateAlignSize_ = 0;
296	        indicesPerLoad_ = 0;
297	        maxIndicesPerLoad_ = 0;
298	        return ge::GRAPH_SUCCESS;
299	    }
300	
301	    // ========== 步骤1: 计算对齐后的每行数据大小 ==========
302	    // 一行indices: 2个元素 * indicesTypeSize 字节, 用GetValue取出，不需要对齐
303	    oneIndexSize_ = INDICES_LAST_DIM * indicesTypeSize_;
304	    // 一行update: D个元素 * updateTypeSize 字节, 对齐到32字节
305	    oneUpdateAlignSize_ = AlignUp(D_ * updateTypeSize_, ALIGN_BYTES);
306	
307	    // ========== 步骤2: 分核策略 ==========
308	    // 按indices行数均分到各核
309	    eachCoreIndexCount_ = CeilDiv(totalIndicesCount_, static_cast<int64_t>(totalCoreNum_));
310	    // 实际使用的核数（可能小于totalCoreNum）
311	    usedCoreNum_ = static_cast<int32_t>(CeilDiv(totalIndicesCount_, eachCoreIndexCount_));
312	    // 最后一个核处理的行数（尾块）
313	    tailCoreIndexCount_ = totalIndicesCount_ - eachCoreIndexCount_ * (usedCoreNum_ - 1);
314	
315	    // ========== 步骤3: UB内存计算 (double buffer) ==========
316	    // 预留一部分UB空间给栈和临时变量
317	    int64_t availableUbSize = ubSize_ - RESERVED_UB_SIZE;
318	    OP_CHECK_IF(availableUbSize <= 0,
319	        OP_LOGE(context_->GetNodeName(),
320	                "UB size(%ld) too small after reserving %ld bytes", ubSize_, RESERVED_UB_SIZE),
321	        return ge::GRAPH_FAILED);
322	
323	    // double buffer: 可用UB分两半
324	    int64_t halfUbSize = availableUbSize / DOUBLE_BUFFER_NUM;
325	
326	    // 每半UB能装多少行 indices + update
327	    int64_t perLoadSize = oneIndexSize_ + oneUpdateAlignSize_;
328	    OP_CHECK_IF(perLoadSize <= 0,
329	        OP_LOGE(context_->GetNodeName(), "perLoadSize should be positive"),
330	        return ge::GRAPH_FAILED);
331	
332	    indicesPerLoad_ = halfUbSize / perLoadSize;
333	    OP_CHECK_IF(indicesPerLoad_ <= 0,
334	        OP_LOGE(context_->GetNodeName(),
335	                "UB too small for 1 row, halfUb=%ld, oneIndex=%ld, oneUpdate=%ld",
336	                halfUbSize, oneIndexSize_, oneUpdateAlignSize_),
337	        return ge::GRAPH_FAILED);
338	
339	    // ========== 步骤4: 限制最大加载行数不超过每核处理量 ==========
340	    maxIndicesPerLoad_ = std::min(eachCoreIndexCount_, indicesPerLoad_);
341	    maxIndicesPerLoad_ = std::min(maxIndicesPerLoad_, static_cast<int64_t>(DATA_COPY_MAX_BLOCK));
342	
343	    OP_LOGD(context_->GetNodeName(),
344	        "totalIndices=%ld, usedCores=%d, eachCore=%ld, tail=%ld, perLoad=%ld, "
345	        "maxPerLoad=%ld, oneIdx=%ld, oneUpd=%ld",
346	        totalIndicesCount_, usedCoreNum_, eachCoreIndexCount_,
347	        tailCoreIndexCount_, indicesPerLoad_, maxIndicesPerLoad_,
348	        oneIndexSize_, oneUpdateAlignSize_);
349	
350	    tilingKey_ = FULL_LOAD_TILING_KEY;
351	
352	    return ge::GRAPH_SUCCESS;
353	}
354	
355	void AiInfraScatterBlockUpdateBaseTiling::PrintTilingData()
356	{
357	    OP_LOGD(context_->GetNodeName(),
358	        "TilingData: totalIndicesCount=%ld, updateDimSize=%ld, usedCoreNum=%d, "
359	        "eachCoreIndexCount=%ld, tailCoreIndexCount=%ld, oneIndexAlign=%ld, "
360	        "oneUpdateAlign=%ld, indicesPerLoad=%ld, maxIndicesPerLoad=%ld, "
361	        "inputStride0=%ld, inputStride1=%ld, indicesTypeSize=%ld, updateTypeSize=%ld",
362	        tilingData_.get_totalIndicesCount(), tilingData_.get_updateDimSize(),
363	        tilingData_.get_usedCoreNum(), tilingData_.get_eachCoreIndexCount(),
364	        tilingData_.get_tailCoreIndexCount(), tilingData_.get_oneIndexSize(),
365	        tilingData_.get_oneUpdateAlignSize(), tilingData_.get_indicesPerLoad(),
366	        tilingData_.get_maxIndicesPerLoad(), tilingData_.get_inputStride0(),
367	        tilingData_.get_inputStride1(), tilingData_.get_indicesTypeSize(),
368	        tilingData_.get_updateTypeSize());
369	}
370	
371	uint64_t AiInfraScatterBlockUpdateBaseTiling::GetTilingKey() const
372	{
373	    return tilingKey_;
374	}
375	
376	ge::graphStatus AiInfraScatterBlockUpdateBaseTiling::PostTiling()
377	{
378	    // ========== 设置所有TilingData字段 ==========
379	    tilingData_.set_totalIndicesCount(totalIndicesCount_);
380	    tilingData_.set_updateDimSize(updateDimSize_);
381	    tilingData_.set_totalCoreNum(totalCoreNum_);
382	    tilingData_.set_ubSize(ubSize_);
383	    tilingData_.set_eachCoreIndexCount(eachCoreIndexCount_);
384	    tilingData_.set_usedCoreNum(usedCoreNum_);
385	    tilingData_.set_tailCoreIndexCount(tailCoreIndexCount_);
386	    tilingData_.set_oneIndexSize(oneIndexSize_);
387	    tilingData_.set_oneUpdateAlignSize(oneUpdateAlignSize_);
388	    tilingData_.set_indicesPerLoad(indicesPerLoad_);
389	    tilingData_.set_maxIndicesPerLoad(maxIndicesPerLoad_);
390	    tilingData_.set_inputStride0(inputStride0_);
391	    tilingData_.set_inputStride1(inputStride1_);
392	    tilingData_.set_indicesTypeSize(indicesTypeSize_);
393	    tilingData_.set_updateTypeSize(updateTypeSize_);
394	
395	    PrintTilingData();
396	
397	    // 校验TilingData大小对齐到8字节
398	    OP_CHECK_IF(tilingData_.GetDataSize() % sizeof(uint64_t) != 0,
399	        OP_LOGE(context_->GetNodeName(), "tiling data size[%zu] is not aligned to 8", tilingData_.GetDataSize()),
400	        return ge::GRAPH_FAILED);
401	
402	    OP_CHECK_NULL_WITH_CONTEXT(context_, context_->GetRawTilingData());
403	    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
404	    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());
405	
406	    // 设置block维度（实际使用的核数）
407	    context_->SetBlockDim(usedCoreNum_);
408	
409	    // 设置workspace（本算子为原地更新，不需要额外workspace）
410	    size_t *workspaces = context_->GetWorkspaceSizes(1);
411	    OP_CHECK_IF(workspaces == nullptr, OPS_REPORT_CUBE_INNER_ERR(context_->GetNodeName(), "workspaces is null"),
412	        return ge::GRAPH_FAILED);
413	    workspaces[0] = workspaceSize_;
414	
415	    return ge::GRAPH_SUCCESS;
416	}
