/*!
 * \file ai_infra_scatter_block_update.cpp
 * \brief Kernel entry point for AiInfraScatterBlockUpdate operator.
 *        DTYPE_INPUT / DTYPE_INDICES are compile-time type macros
 *        provided by the build system based on OpDef input declarations.
 */

#include "kernel_operator.h"
#include "ai_infra_scatter_block_update.h"

using namespace AscendC;

#define FULL_LOAD_TILING_KEY 1000

extern "C" __global__ __aicore__ void ai_infra_scatter_block_update(
    GM_ADDR input, GM_ADDR indices, GM_ADDR update, GM_ADDR input_out, GM_ADDR workspace, GM_ADDR tiling)
{
    GET_TILING_DATA(tilingData, tiling);
    TPipe pipe;
    if (TILING_KEY_IS(FULL_LOAD_TILING_KEY)) {
        ScatterBlockUpdateKernel<DTYPE_INPUT, DTYPE_INDICES> op;
        op.Init(input, indices, update, tilingData, &pipe);
        op.Process();
    }
}

